{"command":"cat > /work/test_fix.py << 'EOF'
import click
import pytest
import sys
sys.path.insert(0, '/work/src')

def test_func_type_with_valueerror_message():
    """Test that a function type uses ValueError message when available."""
    def parse_port(value):
        if not (1 <= int(value) <= 65535):
            raise ValueError("port must be between 1 and 65535")
        return int(value)

    # When ValueError has a message, it should be used
    with pytest.raises(click.BadParameter) as exc_info:
        click.types.FuncParamType(parse_port).convert("70000", None, None)

    assert exc_info.value.message == "port must be between 1 and 65535"
    assert "port must be between 1 and 65535" in exc_info.value.format_message()

def test_func_type_without_valueerror_message():
    """Test that a function type shows the value when ValueError has no message."""
    def parse_port(value):
        if not (1 <= int(value) <= 65535):
            raise ValueError()
        return int(value)

    # When ValueError has no message, it should show the value
    with pytest.raises(click.BadParameter) as exc_info:
        click.types.FuncParamType(parse_port).convert("70000", None, None)

    assert exc_info.value.message == "70000"
    assert "70000" in exc_info.value.format_message()

def test_func_type_with_empty_string_message():
    """Test that a function type shows the value when ValueError message is empty string."""
    def parse_port(value):
        if not (1 <= int(value) <= 65535):
            raise ValueError("")
        return int(value)

    # When ValueError message is empty string, it should show the value
    with pytest.raises(click.BadParameter) as exc_info:
        click.types.FuncParamType(parse_port).convert("70000", None, None)

    assert exc_info.value.message == "70000"
    assert "70000" in exc_info.value.format_message()

if __name__ == '__main__':
    pytest.main([__file__, "-v"])
